torch.set_num_threads(8);torch.manual_seed(1087);torch.cuda.init();device=resolve_physical_device();monitor=_GpuProcessMonitor(device['gpu'],os.getpid(),1);monitor.start()
build=pathlib.Path('/media/IntelSSD/fireprot/runtime/atlas_batched_transpose_probe');build.mkdir(parents=True,exist_ok=True)
ext=load(name='atlas_batched_transpose_probe',sources=['/tmp/fireprot_atlas_batched_transpose_probe.cu'],build_directory=str(build),extra_cuda_cflags=['-O3'],verbose=True)
